if(a==='pay'){title='Pembayaran layanan';body=`<div class="total11"><span>${E(o.service.name)}</span><strong>${money10(o.amount)}</strong></div><p>Pembayaran simulasi untuk pratinjau. Tidak menarik uang atau kredit.</p>${check('Konfirmasi pembayaran simulasi berhasil.')}`;submit='Konfirmasi pembayaran simulasi'}
if(a==='complete-materials'){title='Lengkapi bahan';body=`<p class="notice111">${E(o.message)}</p>${note}<label>Bahan tambahan (opsional)<input type="file" name="materialsfile" multiple accept="image/png,image/jpeg,image/webp,video/mp4,audio/mpeg,audio/wav,application/pdf,application/zip"></label><p>Sertakan rincian atau tautan bahan yang diminta. Pesanan dan pembayaran tetap sama.</p>`;submit='Kirim kelengkapan'}
